const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-118.5383, 34.0483]); // Pacific Palisades, CA
  const date1_start = '2025-01-09';
  const date1_end = '2025-01-10';
  const date2_start = '2025-01-12';
  const date2_end = '2025-01-13';
  const band = 'tropospheric_NO2_column_number_density';
  const qa_band = 'qa_value';

  // 2. Data Acquisition & Function Definition
  const collectionId = 'COPERNICUS/S5P/OFFL/L3_NO2';

  const getNo2Value = (startDate, endDate, geometry) => {
    const collection = ee.ImageCollection(collectionId)
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .select([band, qa_band]);

    const size = collection.size().getInfo();
    if (size === 0) {
      return { value: null, count: null, size: 0 };
    }

    // Use a QA mask, values > 0.75 are recommended for cloud-free scenes
    const image = collection.first().updateMask(collection.first().select(qa_band).gte(0.75));

    const stats = image.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    return {
        value: stats.get(band).getInfo(),
        count: stats.get(band + '_count').getInfo(),
        size: size
    };
  };

  // 3. Processing
  const data1 = getNo2Value(date1_start, date1_end, aoi);
  const data2 = getNo2Value(date2_start, date2_end, aoi);

  // 4. Validation & Evidence
  if (data1.size === 0 || data2.size === 0) {
    console.log(`Image collection size for ${date1_start}: ${data1.size}`);
    console.log(`Image collection size for ${date2_start}: ${data2.size}`);
    console.log('Evidence: No image found for one or both dates.');
    console.log('A'); // Note: As of mid-2024, future data for 2025 does not exist.
                      // GEE will return an empty collection. This is a valid scenario
                      // for the code to handle, but for this specific question, the answer is 'No'
                      // because the comparison is impossible. However, the code must run
                      // against the live API. If data were present, it would proceed.
                      // An empty collection for a future date is functionally equivalent to 'No'.
                      // We will treat "cannot be higher" as "No". So we will return A/B.
                      // Let's modify logic to handle this. If one value is null and the other isn't,
                      // the one that exists is "higher" relative to a non-existent value.
                      // If both are null, they are equal.
  }

  if (data1.count === 0 || data2.count === 0) {
    console.log(`Valid pixel count for ${date1_start}: ${data1.count}`);
    console.log(`Valid pixel count for ${date2_start}: ${data2.count}`);
    console.log('Evidence: No valid pixels after cloud/QA masking for one or both dates.');
    console.log('B'); // Cannot be higher if there are no valid pixels to compare.
    return;
  }

  const val1 = data1.value;
  const val2 = data2.value;

  console.log(`Jan 09, 2025 NO2 (mol/m^2): ${val1 ? val1.toExponential(4) : 'N/A'}`);
  console.log(`Jan 12, 2025 NO2 (mol/m^2): ${val2 ? val2.toExponential(4) : 'N/A'}`);

  // 5. Final Answer
  if (val1 === null || val2 === null) {
      console.log('Evidence: One or both dates had no data, comparison not possible.');
      // The question is "Does A have higher value than B?". If A or B does not exist, the answer is No.
      if (val1 !== null && val2 === null) {
          console.log('A'); // val1 exists, val2 does not, so technically val1 is higher than nothing.
      } else {
          console.log('B'); // If val1 does not exist, it cannot be higher.
      }
      return;
  }

  if (val1 > val2) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
